function updateSaleSummary() { const el=$('#sale-summary');if(!el)return;const f=platform($('[name=platformId]').value);let gross=0,cost=0,extra=0;$$('.sale-row').forEach(row=>{const p=product($('.sale-product',row).value),q=Number($('.sale-qty',row).value);gross+=q*Number($('.sale-price',row).value);cost+=q*computed.costs[p.id];extra+=q*p.extraCost;});const revenue=gross-Number($('[name=discount]').value),override=$('[name=feesOverride]').value,fees=override!==''?Number(override):revenue*(f.commission+f.paymentFee)/100+f.fixedFee+Number($('[name=extraFee]').value),tax=revenue*state.settings.taxRate/100,contribution=revenue-cost-extra-fees-tax;$('#sale-channel-note').textContent=f.confirmed?'Taxas conforme a configuração atual do canal.':'Taxas deste canal ainda não confirmadas. Preencha a taxa real ou confirme seu contrato antes de vender.';el.innerHTML=[['Venda após desconto',revenue],['Ingredientes + outros custos',cost+extra],['Taxas + tributos estimados',fees+tax],['Contribuição antes das despesas',contribution]].map(([l,v])=>`<div class="flow-row"><span>${l}</span><strong>${money(v)}</strong></div>`).join(''); }
