function movementsModal() { const list=state.movements.slice().reverse().slice(0,150);const names={purchase:'Compra',sale:'Venda',loss:'Perda',gain:'Ajuste de entrada',return:'Devolução',opening:'Saldo inicial',set:'Inventário'};modal('Movimentações de estoque',`<div class="history-list">${list.length?`<div class="table-wrap"><table><thead><tr><th>Data / item</th><th>Movimento</th><th>Quantidade</th></tr></thead><tbody>${list.map(m=>`<tr><td>${dateLabel(m.date)}<div>${esc(ingredient(m.ingredientId)?.name||m.ingredientName)}</div></td><td>${esc(names[m.kind]||m.kind)}<div class="small muted">${esc(m.reason||m.note||'')}</div>${m.affectsStock===false?'<div class="small muted">Baixa já registrada na venda</div>':''}</td><td class="numeric">${m.lossCategory==='preparation'?money(m.cost):qty(m.quantity,ingredient(m.ingredientId)||{dimension:'count'})}</td></tr>`).join('')}</tbody></table></div>`:'<p>Nenhum movimento registrado.</p>'}</div><details><summary>Compras e validades informadas</summary><div class="history-list">${state.purchases.slice().reverse().slice(0,100).map(p=>`<div class="stock-alert"><div><strong>${esc(ingredient(p.ingredientId)?.name)}</strong><div class="small muted">Compra: ${dateLabel(p.date)} · ${esc(p.supplier||'Fornecedor não informado')}</div><div class="small">Validade: ${p.expiry?dateLabel(p.expiry):'não informada'} · ${esc(p.note||'')}</div></div><strong>${money(p.totalCost)}</strong></div>`).join('')||'<p>Sem compras.</p>'}</div></details>`,async()=>{});$('.form-actions',$('#dialog')).innerHTML='<button class="primary" type="button" data-close>Fechar</button>'; }
function saleDetail(id) { const s=state.sales.find(s=>s.id===id);modal('Detalhes do pedido',`<p><strong>${dateLabel(s.date)} · ${esc(s.platformName||platform(s.platformId)?.name)}</strong></p><p class="small">${esc(s.note||'Sem observação')}</p>${[['Venda após desconto',s.revenue],['Desconto da loja',s.discount],['Taxas plataforma',s.fees],['Tributos estimados',s.taxes],['Ingredientes',s.cogs],['Outros custos dos produtos',s.extraCosts],['Contribuição',s.contribution]].map(([l,v])=>`<div class="flow-row"><span>${l}</span><strong>${money(v)}</strong></div>`).join('')}<div class="divider"></div><h3>Ingredientes consumidos</h3>${s.consumed.map(c=>`<div class="flow-row"><span>${esc(c.name||c.ingredientName||ingredient(c.ingredientId)?.name)}</span><strong>${qty(c.quantity,ingredient(c.ingredientId)||{dimension:'count'})}</strong></div>`).join('')}<p class="small muted">Fiscal: ${esc(s.fiscalStatus||'pending')} · ${esc(s.fiscalReference||'sem referência')}</p>${s.status==='canceled'?`<div class="notice">Cancelado. ${s.canceledRestock?'Estoque devolvido.':'Ingredientes contabilizados como perda.'}</div>`:''}`,async()=>{});$('.form-actions',$('#dialog')).innerHTML='<button class="primary" type="button" data-close>Fechar</button>'; }
function cancelSale(id) { modal('Cancelar pedido',`<div class="notice">A venda sairá do resultado. Informe se os ingredientes podem voltar ao estoque físico.</div><label class="check-row"><input type="checkbox" name="restock"><span>Os ingredientes não foram utilizados e voltam ao estoque</span></label><p class="hint">Se o produto já foi preparado, deixe desmarcado: o custo dos ingredientes e os demais custos de produção serão registrados como perda.</p>`,f=>api('sales/cancel',{id,restock:$('[name=restock]',f).checked}));$('button[type=submit]',$('#modal-form')).textContent='Confirmar cancelamento'; }
function fiscalModal(id) { const s=state.sales.find(s=>s.id===id);modal('Atualizar situação fiscal',`<div class="form-grid">${select('Situação fiscal','fiscalStatus',[['pending','Pendente de verificar'],['exempt','Dispensa de emissão aplicável'],['issued','Documento já emitido']],s.fiscalStatus)}${field('Número / chave do documento','fiscalReference','text',s.fiscalReference,'maxlength="150"')}</div><p class="hint">Informe o documento emitido no seu emissor fiscal. Essa atualização preserva o estoque e os custos da venda.</p>`,f=>api('sales/fiscal',{...vals(f),id})); }
function confirmAction(title,text,route,payload) { modal(title,`<p>${text}</p>`,()=>api(route,payload));$('button[type=submit]',$('#modal-form')).textContent='Confirmar'; }
function restoreModal() { modal('Restaurar backup',`<div class="notice">A restauração substitui os dados atuais pelos dados do backup. Uma cópia da base atual será guardada na pasta data/backups antes da tentativa.</div><label class="field">Backup JSON do Brasa<input type="file" name="backup" accept=".json,application/json" required></label><label class="check-row"><input type="checkbox" required><span>Conferi o arquivo e quero substituir os dados atuais</span></label>`,async f=>{const file=$('[name=backup]',f).files[0];if(file.size>64*1024*1024)throw Error('Backup maior que 64 MB. Para bases maiores, copie a pasta data com o programa encerrado.');let data;try{data=JSON.parse(await file.text());}catch{throw Error('O arquivo não contém um JSON válido.');}await api('restore',data);}); }
document.addEventListener('click',e=>{
  if(e.target.closest('[data-close]'))return $('#dialog').close();
  const choose=e.target.closest('[data-image-index]');if(choose){++imageSearchVersion;imageValue=imageResults[Number(choose.dataset.imageIndex)];imageManual=true;updateImagePreview();return;}
  const remove=e.target.closest('.remove-row');if(remove){const parent=remove.closest('.recipe-row,.sale-row');if(parent.parentNode.children.length>1){parent.remove();updateRecipeSummary();updateSaleSummary();}else toast('Mantenha pelo menos um item.');return;}
  const a=e.target.closest('[data-action]');if(!a)return;
  const id=a.dataset.id;const actions={ingredient:()=>ingredientModal(id),purchase:()=>purchaseModal(id),product:()=>productModal(id),sale:saleModal,adjust:()=>adjustmentModal(id),expense:expenseModal,platform:()=>platformModal(id),movements:movementsModal,'sale-detail':()=>saleDetail(id),'sale-fiscal':()=>fiscalModal(id),'cancel-sale':()=>cancelSale(id),restore:restoreModal,price:()=>{selectedProduct=id;location.hash='pricing';if(currentPage==='pricing')render();},demo:()=>confirmAction('Explorar com exemplos','Vamos criar ingredientes, fichas e compras fictícias para você experimentar. Use somente em uma base vazia; esses valores não representam seu negócio.','demo',{}),'delete-expense':()=>confirmAction('Excluir despesa','Esta despesa será removida do resultado do mês.','expenses/delete',{id})};actions[a.dataset.action]?.();if(a.dataset.action==='sale-detail') $('.form-actions', $('#dialog')).insertAdjacentHTML('afterbegin',action('Atualizar situação fiscal','sale-fiscal',id,'secondary'));
});
document.addEventListener('input',e=>{if(e.target.id==='ingredient-search')filterIngredients();});document.addEventListener('change',e=>{if(e.target.id==='stock-filter')filterIngredients();});
$('#month').addEventListener('change',()=>load().catch(e=>toast(e.message)));$('#menu-button').onclick=()=>{const open=$('.sidebar').classList.toggle('open');$('#menu-button').setAttribute('aria-expanded',String(open));};
window.addEventListener('hashchange',()=>{if(state)render();});
$('#dialog').addEventListener('close',()=>{clearTimeout(imageTimer);++imageSearchVersion;});
try { await load(); const r=await fetch('/guide.json');if(r.ok){guide=await r.json();if(currentPage==='guide')render();} } catch(e) { $('#main').innerHTML=`<section class="panel"><div class="panel-body"><h1>Não foi possível carregar</h1><p>${esc(e.message)}</p><button class="primary" id="reload">Tentar novamente</button></div></section>`;$('#reload').onclick=()=>location.reload(); }
// Structured read access for compatible browsers; uses the same persisted data as the UI.
if (document.modelContext?.registerTool) {
  const lifecycle = new AbortController();
  window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
  for (const tool of [
    {name:'read_hamburgueria_inventory',title:'Consultar estoque',description:'Read current ingredient stock and average cost from the local hamburgueria manager.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async input=>{if(!input||Object.keys(input).length)throw Error('Sem parâmetros.');const data=await api('state');return {ingredients:data.state.ingredients.map(i=>({id:i.id,name:i.name,stock:i.stock,unit:i.unit,avgCost:i.avgCost,minStock:i.minStock}))};}},
    {name:'read_hamburgueria_monthly_result',title:'Consultar resultado mensal',description:'Read recorded revenue, historic costs, expenses and net result for an explicit month.',inputSchema:{type:'object',properties:{month:{type:'string',pattern:'^\\d{4}-(0[1-9]|1[0-2])$'}},required:['month'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async input=>{if(!input||Object.keys(input).some(k=>k!=='month')||!/^\d{4}-(0[1-9]|1[0-2])$/.test(input.month))throw Error('Informe um mês AAAA-MM.');const data=await api(`state?month=${input.month}`);return data.report;}}
  ]) { try { await document.modelContext.registerTool(tool,{signal:lifecycle.signal}); } catch { /* optional browser capability */ } }
}
